-- Browser clients can only subscribe to these opaque invalidation signals.
-- Operational data is read and changed through authenticated server services.
create table profiles (id uuid primary key, role text not null check(role in ('OWNER','ADMIN','KITCHEN')));
create table store_settings (singleton boolean primary key default true check(singleton), value jsonb not null);
create table store_signals (topic text primary key check(topic in ('public','staff','kitchen')), version bigint not null default 0);
create table delivery_zones (id uuid primary key default gen_random_uuid(), name text not null, fee integer not null check(fee>=0), postcodes text[] not null, enabled boolean not null default true);
create table promotions (id uuid primary key default gen_random_uuid(),code text not null unique, percent numeric(5,2) not null check(percent between 0 and 100),enabled boolean not null default false);
create table products (id uuid primary key default gen_random_uuid(),name text not null,description text not null,price integer not null check(price>=0),image text not null, ingredients text[] not null default '{}',removable text[] not null default '{}',available boolean not null,archived boolean not null default false,position integer not null,check(removable <@ ingredients));
create table ingredients (id uuid primary key default gen_random_uuid(),name text not null,unit text not null check(unit in ('g','ml','pz')),stock numeric(16,4) not null default 0 check(stock>=0),minimum numeric(16,4) not null default 0 check(minimum>=0),supplier text not null default '',purchase_quantity numeric(16,4) not null default 0 check(purchase_quantity>=0),purchase_price integer not null default 0 check(purchase_price>=0),purchase_unit text not null,presentation text not null default '',purchase_date date,unit_cost numeric(18,8) check(unit_cost>=0));
create table recipes (product_id uuid primary key references products,complete boolean not null default false);
create table recipe_items (product_id uuid not null references recipes,ingredient_id uuid not null references ingredients,quantity numeric(16,4) not null check(quantity>0),unit text not null,base_quantity numeric(16,4) not null check(base_quantity>0),category text not null check(category in ('masa','salsa','toppings','empaque','otros')),primary key(product_id,ingredient_id,category));
create index recipe_items_by_ingredient on recipe_items(ingredient_id);
create table ingredient_purchases(id uuid primary key default gen_random_uuid(),ingredient_id uuid not null references ingredients,quantity numeric(16,4) not null check(quantity>0),unit text not null,base_quantity numeric(16,4) not null check(base_quantity>0),price integer not null check(price>=0),supplier text not null,date date not null);
create table dough_batches (id uuid primary key default gen_random_uuid(),prepared_at timestamptz not null,flour numeric not null check(flour>=0),hydration numeric not null check(hydration between 0 and 150),yeast numeric not null check(yeast>=0),salt numeric not null check(salt>=0),ball_weight numeric not null check(ball_weight>0),balls integer not null check(balls>0),remaining integer not null check(remaining between 0 and balls),ferment_start timestamptz not null,ferment_hours numeric not null check(ferment_hours>=0),expires_at timestamptz not null,status text not null check(status in ('preparing','fermenting','ready','waste')),check(expires_at>prepared_at));
create table sales_channels (id text primary key,name text not null,commission numeric(5,2) check(commission between 0 and 100));
create table orders (id uuid primary key default gen_random_uuid(),number integer generated by default as identity unique,token text not null unique,request_key text not null unique,request_hash text not null,status text not null check(status in ('pending','confirmed','preparing','baking','ready','dispatched','delivered','picked_up','cancelled','review')),payment_status text not null default 'pending',mode text not null check(mode in ('pickup','delivery')),customer_name text not null,phone text not null,email text not null,address text not null,postcode text not null,delivery_references text not null,notes text not null,subtotal integer not null check(subtotal>=0),fee integer not null check(fee>=0),discount integer not null check(discount>=0),total integer not null check(total>=0 and total=subtotal+fee-discount),channel text not null references sales_channels,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),expires_at timestamptz not null,paid_at timestamptz);
create index orders_active on orders(status, expires_at);
create index orders_paid on orders(paid_at);
create table order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,product_id uuid not null references products,name text not null,image text not null,unit_price integer not null check(unit_price>=0),unit_cost integer check(unit_cost>=0),partial_cost integer not null check(partial_cost>=0),quantity integer not null check(quantity between 1 and 50),removed text[] not null,note text not null);
create index order_items_parent on order_items(order_id);
create table ovens (id text primary key,name text not null,capacity integer not null check(capacity>0),temperature integer not null check(temperature>0),seconds integer not null check(seconds>0));
create table order_item_units (id uuid primary key default gen_random_uuid(),item_id uuid not null references order_items,ordinal integer not null,status text not null default 'queued' check(status in ('queued','baking','ready')),oven_id text references ovens,started_at timestamptz,ends_at timestamptz,finished_at timestamptz,unique(item_id,ordinal));
create index units_baking on order_item_units(oven_id,status) where status='baking';
create table inventory_reservations (id uuid primary key default gen_random_uuid(),order_id uuid not null references orders,ingredient_id uuid references ingredients,batch_id uuid references dough_batches,quantity numeric(16,4) not null check(quantity>0),status text not null check(status in ('held','consumed','released')),check(num_nonnulls(ingredient_id,batch_id)=1));
create index holds_order on inventory_reservations(order_id);
create index ingredient_holds on inventory_reservations(ingredient_id) where status='held';
create index dough_holds on inventory_reservations(batch_id) where status='held';
create table inventory_movements (id uuid primary key default gen_random_uuid(),ingredient_id uuid references ingredients,batch_id uuid references dough_batches,quantity numeric(16,4) not null,type text not null,reason text not null,order_id uuid references orders,reservation_id uuid unique references inventory_reservations,date timestamptz not null default now(),check(num_nonnulls(ingredient_id,batch_id)=1));
create index movements_ingredient on inventory_movements(ingredient_id,date);
create table payments(id text primary key,order_id uuid not null references orders,amount integer not null,currency text not null,status text not null,refunded integer not null default 0,fee integer,updated_at timestamptz not null);
create index payments_order on payments(order_id);
create table payment_events(id text primary key,payment_id text not null,order_id uuid references orders,status text not null,received_at timestamptz not null default now());
create table finance_sales(id uuid primary key default gen_random_uuid(),order_id uuid unique references orders,date timestamptz not null,channel text not null references sales_channels,gross integer not null check(gross>=0),discount integer not null check(discount>=0),refund integer not null default 0 check(refund>=0),fee integer check(fee>=0),cost integer check(cost>=0),units integer not null check(units>=0),product_sales jsonb not null);
create index finance_period on finance_sales(date,channel);
create table expenses(id uuid primary key default gen_random_uuid(),name text not null,category text not null,amount integer not null check(amount>0),date date not null,receipt text not null default '');
create table notification_events (id uuid primary key default gen_random_uuid(),dedupe text not null unique,type text not null,recipient text not null,subject text not null,order_id uuid references orders,payload jsonb not null,state text not null default 'pending' check(state in ('pending','leased','sent','failed','skipped')),attempts integer not null default 0,available_at timestamptz not null default now(),lease_until timestamptz,created_at timestamptz not null default now(),last_error text);
create index outbox_ready on notification_events(available_at) where state in ('pending','leased');
create table audit_logs(id bigint generated always as identity primary key,actor text not null,action text not null,entity text,created_at timestamptz not null default now());
create table rate_limits(key text primary key,hits integer not null,expires_at timestamptz not null);
do $$ declare n text; begin
  foreach n in array array['profiles','store_settings','store_signals','delivery_zones','promotions','products','ingredients','recipes','recipe_items','ingredient_purchases','dough_batches','sales_channels','orders','order_items','ovens','order_item_units','inventory_reservations','inventory_movements','payments','payment_events','finance_sales','expenses','notification_events','audit_logs','rate_limits'] loop
    execute format('alter table public.%I enable row level security',n);
    if exists(select 1 from pg_roles where rolname='anon') then execute format('revoke all privileges on public.%I from anon,authenticated',n); end if;
  end loop;
  if exists(select 1 from pg_roles where rolname='authenticated') and to_regnamespace('auth') is not null then
    alter table profiles add constraint profiles_auth_fk foreign key(id) references auth.users(id) on delete cascade;
    grant select on profiles to authenticated;
    create policy staff_own_role on profiles for select to authenticated using(id=(select auth.uid()));
    grant select on store_signals to anon,authenticated;
    create policy public_signal on store_signals for select to anon,authenticated using(topic='public');
    create policy staff_signal on store_signals for select to authenticated using(exists(select 1 from profiles where id=(select auth.uid()) and (role in ('OWNER','ADMIN') or (role='KITCHEN' and topic='kitchen'))));
  end if;
  if exists(select 1 from pg_publication where pubname='supabase_realtime') then alter publication supabase_realtime add table public.store_signals; end if;
end $$;
